"""학습 데이터(JSONL chat 형식) 검사 — python validate_jsonl.py train.jsonl

검사 항목: JSON 형식, messages 구조, 역할 순서, 빈 내용, 길이, 중복, 개인정보 의심 패턴.
개인정보 패턴은 예시용이며 사내 기준으로 보완해야 합니다.
"""
import hashlib
import json
import re
import sys
from collections import Counter

ROLES = {"system", "user", "assistant"}
MAX_CHARS = 6000          # 대략적인 길이 상한(토큰 수는 토크나이저로 다시 확인)
PII = {
    "주민등록번호 의심": re.compile(r"\d{6}-?[1-4]\d{6}"),
    "전화번호 의심": re.compile(r"01[016789]-?\d{3,4}-?\d{4}"),
    "이메일": re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+"),
    "긴 숫자열(계좌 등) 의심": re.compile(r"\d{2,6}-\d{2,6}-\d{2,8}"),
}


def check_record(n: int, rec: dict, errors: list, warns: list):
    msgs = rec.get("messages")
    if not isinstance(msgs, list) or len(msgs) < 2:
        errors.append(f"{n}행: messages 가 없거나 2개 미만")
        return
    roles = [m.get("role") for m in msgs]
    if any(r not in ROLES for r in roles):
        errors.append(f"{n}행: 알 수 없는 role {roles}")
    if roles[-1] != "assistant":
        errors.append(f"{n}행: 마지막 메시지는 assistant(정답)여야 합니다")
    for m in msgs:
        text = m.get("content", "")
        if not isinstance(text, str) or not text.strip():
            errors.append(f"{n}행: 빈 content ({m.get('role')})")
            continue
        for label, pat in PII.items():
            if pat.search(text):
                errors.append(f"{n}행: {label} — 마스킹 후 다시 넣으세요")
    total = sum(len(m.get("content", "")) for m in msgs)
    if total > MAX_CHARS:
        warns.append(f"{n}행: 길이 {total}자 — max_length 에서 잘릴 수 있음")


def main(path: str):
    errors, warns, seen = [], [], Counter()
    answers = Counter()
    count = 0
    for n, line in enumerate(open(path, encoding="utf-8"), 1):
        if not line.strip():
            continue
        count += 1
        try:
            rec = json.loads(line)
        except json.JSONDecodeError as e:
            errors.append(f"{n}행: JSON 오류 {e}")
            continue
        check_record(n, rec, errors, warns)
        seen[hashlib.md5(line.encode()).hexdigest()] += 1
        if rec.get("messages"):
            answers[rec["messages"][-1].get("content", "")[:40]] += 1
    dup = sum(c - 1 for c in seen.values() if c > 1)
    if dup:
        warns.append(f"완전히 같은 행 {dup}개 — 과적합 원인이 됩니다")
    common = answers.most_common(1)
    if common and count >= 20 and common[0][1] / count > 0.3:
        warns.append("정답의 30% 이상이 같은 문장으로 시작합니다 — 다양성을 확인하세요")
    print(f"{'OK' if not errors else 'FAIL'} {count}건 검사 · 오류 {len(errors)} · 경고 {len(warns)}")
    for e in errors[:50]:
        print("  FAIL", e)
    for w in warns[:50]:
        print("  WARN", w)
    sys.exit(1 if errors else 0)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "train.jsonl")

package study.s22;

import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * 파인튜닝 vs RAG 판단 체크리스트 — Python 트랙 decide.py 와 같은 규칙, 같은 answers.yaml.
 *   ./mvnw -q compile exec:java -Dexec.args=answers.yaml
 */
public final class Decide {

    static List<String> decide(Map<String, Object> a) {
        List<String> out = new ArrayList<>();
        if (!bool(a, "prompt_tried")) {
            return List.of("먼저 프롬프트(규칙 + 예시 3~5개)로 평가셋을 돌려 보세요. 대부분 여기서 해결됩니다.");
        }
        if (num(a, "prompt_score", 0) >= num(a, "target_score", 0.9)) {
            return List.of("프롬프트로 목표를 넘었습니다. 추가 작업 없이 운영하고 평가셋만 주기적으로 다시 돌립니다.");
        }
        if (bool(a, "needs_new_facts") || bool(a, "facts_change_often") || bool(a, "needs_citation")) {
            out.add("RAG: 모르는 사실·자주 바뀌는 문서·출처 요구는 검색으로 해결합니다 (세션 9~10).");
        }
        if (bool(a, "format_or_tone_issue")) {
            int n = (int) num(a, "labeled_examples", 0);
            if (n < 200) {
                out.add("파인튜닝 보류: 검수된 예시가 " + n + "건뿐입니다. 200건 이상(권장 500~1,000건) 모을 때까지 "
                        + "RAG 로 비슷한 예시를 찾아 프롬프트에 붙이는 방식(동적 few-shot)을 씁니다.");
            } else if (!bool(a, "has_gpu")) {
                out.add("파인튜닝 후보: 데이터는 충분하지만 GPU 가 없습니다. 학습용 GPU 확보 계획부터 세웁니다.");
            } else {
                out.add("LoRA 파인튜닝: 형식·말투 문제이고 예시 " + n + "건이 있으므로 작은 LoRA 로 시도합니다.");
            }
        }
        if (out.isEmpty()) {
            out.add("원인 분석 필요: 실패 사례 20건을 직접 읽고 '사실 부족'인지 '형식 문제'인지 분류해 보세요.");
        }
        return out;
    }

    static boolean bool(Map<String, Object> a, String k) {
        return Boolean.TRUE.equals(a.get(k));
    }

    static double num(Map<String, Object> a, String k, double def) {
        return a.get(k) instanceof Number n ? n.doubleValue() : def;
    }

    public static void main(String[] args) throws IOException {
        Path file = Path.of(args.length > 0 ? args[0] : "answers.yaml");
        Map<String, Object> answers;
        try (Reader r = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
            answers = new Yaml(new SafeConstructor(new LoaderOptions())).load(r);
        }
        System.out.println("[" + answers.getOrDefault("name", "유스케이스") + "]");
        decide(answers).forEach(line -> System.out.println("- " + line));
    }
}

package study.s22;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * 학습 데이터(JSONL chat 형식) 검사와 분할 — 학습 앞단을 Java 로 맡습니다.
 *
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s22.DatasetTool -Dexec.args="validate train.jsonl"
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s22.DatasetTool -Dexec.args="split all.jsonl 0.1 42"
 *
 * validate: Python 트랙 validate_jsonl.py 와 같은 항목 (형식 · 역할 순서 · 빈 내용 · 길이 · 중복 · 개인정보 의심 패턴)
 * split   : 같은 메모(user 내용)가 train 과 eval 양쪽에 들어가지 않게 나눕니다 (평가 점수 부풀림 방지)
 * 개인정보 패턴은 예시용이며 사내 기준으로 보완해야 합니다.
 */
public final class DatasetTool {

    static final ObjectMapper JSON = new ObjectMapper();
    static final Set<String> ROLES = Set.of("system", "user", "assistant");
    static final int MAX_CHARS = 6000;   // 대략적인 길이 상한 (토큰 수는 토크나이저로 다시 확인)
    static final Map<String, Pattern> PII = new LinkedHashMap<>();

    static {
        PII.put("주민등록번호 의심", Pattern.compile("\\d{6}-?[1-4]\\d{6}"));
        PII.put("전화번호 의심", Pattern.compile("01[016789]-?\\d{3,4}-?\\d{4}"));
        PII.put("이메일", Pattern.compile("[\\w.+-]+@[\\w-]+\\.[\\w.]+"));
        PII.put("긴 숫자열(계좌 등) 의심", Pattern.compile("\\d{2,6}-\\d{2,6}-\\d{2,8}"));
    }

    static void checkRecord(int n, JsonNode rec, List<String> errors, List<String> warns) {
        JsonNode msgs = rec.path("messages");
        if (!msgs.isArray() || msgs.size() < 2) {
            errors.add(n + "행: messages 가 없거나 2개 미만");
            return;
        }
        List<String> roles = new ArrayList<>();
        msgs.forEach(m -> roles.add(m.path("role").asText(null)));
        if (roles.stream().anyMatch(r -> !ROLES.contains(r))) errors.add(n + "행: 알 수 없는 role " + roles);
        if (!"assistant".equals(roles.get(roles.size() - 1))) errors.add(n + "행: 마지막 메시지는 assistant(정답)여야 합니다");
        int total = 0;
        for (JsonNode m : msgs) {
            JsonNode c = m.path("content");
            if (!c.isTextual() || c.asText().isBlank()) {
                errors.add(n + "행: 빈 content (" + m.path("role").asText() + ")");
                continue;
            }
            total += c.asText().length();
            for (var e : PII.entrySet()) {
                if (e.getValue().matcher(c.asText()).find()) errors.add(n + "행: " + e.getKey() + " — 마스킹 후 다시 넣으세요");
            }
        }
        if (total > MAX_CHARS) warns.add(n + "행: 길이 " + total + "자 — max_length 에서 잘릴 수 있음");
    }

    static int validate(Path path) throws IOException {
        List<String> errors = new ArrayList<>(), warns = new ArrayList<>();
        Map<String, Integer> seen = new HashMap<>(), answers = new HashMap<>();
        int count = 0, n = 0;
        for (String line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
            n++;
            if (line.isBlank()) continue;
            count++;
            JsonNode rec;
            try {
                rec = JSON.readTree(line);
            } catch (JsonProcessingException e) {
                errors.add(n + "행: JSON 오류 " + e.getOriginalMessage());
                continue;
            }
            checkRecord(n, rec, errors, warns);
            seen.merge(sha256(line), 1, Integer::sum);
            JsonNode msgs = rec.path("messages");
            if (msgs.isArray() && msgs.size() > 0) {
                String ans = msgs.get(msgs.size() - 1).path("content").asText("");
                answers.merge(ans.substring(0, Math.min(40, ans.length())), 1, Integer::sum);
            }
        }
        int dup = seen.values().stream().mapToInt(c -> c - 1).sum();
        if (dup > 0) warns.add("완전히 같은 행 " + dup + "개 — 과적합 원인이 됩니다");
        int top = answers.values().stream().mapToInt(Integer::intValue).max().orElse(0);
        if (count >= 20 && top / (double) count > 0.3) warns.add("정답의 30% 이상이 같은 문장으로 시작합니다 — 다양성을 확인하세요");

        System.out.printf("%s %d건 검사 · 오류 %d · 경고 %d%n", errors.isEmpty() ? "OK" : "FAIL", count, errors.size(), warns.size());
        errors.stream().limit(50).forEach(e -> System.out.println("  FAIL " + e));
        warns.stream().limit(50).forEach(w -> System.out.println("  WARN " + w));
        return errors.isEmpty() ? 0 : 1;
    }

    /** user 메시지(원문 메모)를 정규화한 키로 묶어, 같은 메모의 변형이 양쪽에 갈리지 않게 나눕니다. */
    static void split(Path all, double evalRatio, long seed) throws IOException {
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String line : Files.readAllLines(all, StandardCharsets.UTF_8)) {
            if (line.isBlank()) continue;
            JsonNode msgs = JSON.readTree(line).path("messages");
            String memo = msgs.size() >= 2 ? msgs.get(msgs.size() - 2).path("content").asText() : line;
            groups.computeIfAbsent(memo.replaceAll("\\s+", "").toLowerCase(), k -> new ArrayList<>()).add(line);
        }
        List<String> keys = new ArrayList<>(groups.keySet());
        Collections.shuffle(keys, new Random(seed));                  // seed 고정 → 다시 나눠도 같은 결과
        int evalGroups = Math.max(1, (int) Math.round(keys.size() * evalRatio));
        List<String> train = new ArrayList<>(), eval = new ArrayList<>();
        for (int i = 0; i < keys.size(); i++) {
            List<String> rows = new ArrayList<>(new LinkedHashSet<>(groups.get(keys.get(i))));   // 완전 중복 제거
            (i < evalGroups ? eval : train).addAll(rows);
        }
        Path dir = all.toAbsolutePath().getParent();
        Files.write(dir.resolve("train.jsonl"), train, StandardCharsets.UTF_8);
        Files.write(dir.resolve("eval.jsonl"), eval, StandardCharsets.UTF_8);
        System.out.printf("메모 %d종 → train %d건 · eval %d건 (seed %d, 같은 메모는 한쪽에만)%n", keys.size(), train.size(), eval.size(), seed);
    }

    static String sha256(String s) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    public static void main(String[] args) throws IOException {
        String cmd = args.length > 0 ? args[0] : "validate";
        if (cmd.equals("split")) {
            split(Path.of(args.length > 1 ? args[1] : "all.jsonl"),
                    args.length > 2 ? Double.parseDouble(args[2]) : 0.1,
                    args.length > 3 ? Long.parseLong(args[3]) : 42L);
        } else {
            System.exit(validate(Path.of(args.length > 1 ? args[1] : "train.jsonl")));
        }
    }
}

package study.s22;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.IntStream;

/**
 * 같은 eval.jsonl 로 세 방식을 비교합니다 — 모두 사내 vLLM(OpenAI 호환) 한 대에서.
 *   base    : 기본 모델 (학습 데이터와 같은 system + 메모)
 *   fewshot : 기본 모델 + 규칙 + train.jsonl 에서 비슷한 옛 보고서 3건 (검색으로 붙이는 동적 few-shot = RAG 방식)
 *   lora    : 기본 모델 + LoRA 어댑터 (요청의 model 을 어댑터 이름으로)
 * 지표: 형식 준수율(필수 항목 5개), 정답과의 글자 겹침(간이). 최종 판단은 사람의 블라인드 비교로 합니다.
 *
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s22.CompareEval
 */
public final class CompareEval {

    static final String BASE_URL = env("LLM_BASE_URL", "http://localhost:8000/v1");
    static final String API_KEY = env("LLM_API_KEY", "change-me");
    static final String BASE_MODEL = env("BASE_MODEL_NAME", "qwen3-0.6b");     // --served-model-name
    static final String LORA_MODEL = env("LORA_MODEL_NAME", "report-style");   // --lora-modules 의 이름
    static final List<String> REQUIRED = List.of("■ 개요", "■ 원인", "■ 조치", "■ 영향", "■ 후속");
    static final String RULES = "사내 장애 보고서 문체로 요약합니다. 반드시 '■ 개요 / ■ 원인 / ■ 조치 / ■ 영향 / ■ 후속' "
            + "다섯 줄로 쓰고, 메모에 없는 사실은 쓰지 않습니다. 시각은 HH:MM 으로 씁니다.";

    static final ObjectMapper JSON = new ObjectMapper();
    static final HttpClient HTTP = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();

    record Example(String system, String memo, String answer) {}

    static String chat(String model, ArrayNode messages) throws IOException, InterruptedException {
        ObjectNode body = JSON.createObjectNode();
        body.put("model", model);
        body.put("max_tokens", 400);
        body.put("temperature", 0);                       // 비교 실험은 결정적으로
        body.set("messages", messages);
        // Qwen3 계열은 기본으로 사고(thinking) 출력을 붙입니다. vLLM 의 chat_template_kwargs 로 끕니다 (모델 카드 확인)
        body.putObject("chat_template_kwargs").put("enable_thinking", false);
        HttpRequest req = HttpRequest.newBuilder(URI.create(BASE_URL + "/chat/completions"))
                .timeout(Duration.ofSeconds(120))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + API_KEY)
                .POST(HttpRequest.BodyPublishers.ofString(body.toString(), StandardCharsets.UTF_8))
                .build();
        HttpResponse<String> res = HTTP.send(req, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        if (res.statusCode() != 200) throw new IOException(model + " HTTP " + res.statusCode() + ": " + res.body());
        return JSON.readTree(res.body()).at("/choices/0/message/content").asText().strip();
    }

    static ArrayNode messages(String system) {
        ArrayNode a = JSON.createArrayNode();
        a.addObject().put("role", "system").put("content", system);
        return a;
    }

    static ArrayNode turn(ArrayNode a, String role, String content) {
        a.addObject().put("role", role).put("content", content);
        return a;
    }

    /** 검색: 글자 2-gram 자카드 유사도 상위 k 개. Python 트랙 fewshot.py 는 multilingual-e5-small 임베딩을 씁니다. */
    static List<Example> similar(List<Example> pool, String memo, int k) {
        Set<String> q = bigrams(memo);
        return pool.stream()
                .sorted(Comparator.comparingDouble((Example e) -> -jaccard(q, bigrams(e.memo()))))
                .limit(k)
                .toList();
    }

    static Set<String> bigrams(String s) {
        String t = s.replaceAll("\\s+", "");
        Set<String> out = new HashSet<>();
        for (int i = 0; i + 2 <= t.length(); i++) out.add(t.substring(i, i + 2));
        return out;
    }

    static double jaccard(Set<String> a, Set<String> b) {
        if (a.isEmpty() || b.isEmpty()) return 0;
        Set<String> inter = new HashSet<>(a);
        inter.retainAll(b);
        return inter.size() / (double) (a.size() + b.size() - inter.size());
    }

    /** Python 트랙 char_f1 과 같은 간이 지표: 공백 뺀 글자 집합의 겹침 */
    static double charF1(String pred, String ref) {
        Set<Integer> p = new HashSet<>(), r = new HashSet<>();
        pred.replace(" ", "").codePoints().forEach(p::add);
        ref.replace(" ", "").codePoints().forEach(r::add);
        if (p.isEmpty() || r.isEmpty()) return 0;
        Set<Integer> inter = new HashSet<>(p);
        inter.retainAll(r);
        return 2.0 * inter.size() / (p.size() + r.size());
    }

    static List<Example> load(Path file) throws IOException {
        List<Example> out = new ArrayList<>();
        for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
            if (line.isBlank()) continue;
            JsonNode m = JSON.readTree(line).path("messages");
            int n = m.size();
            String system = m.get(0).path("role").asText().equals("system") ? m.get(0).path("content").asText() : RULES;
            out.add(new Example(system, m.get(n - 2).path("content").asText(), m.get(n - 1).path("content").asText()));
        }
        return out;
    }

    public static void main(String[] args) throws Exception {
        List<Example> train = load(Path.of("train.jsonl"));
        List<Example> eval = load(Path.of("eval.jsonl"));
        String[] names = {"base", "fewshot", "lora"};
        int[] fmt = new int[3];
        double[] f1 = new double[3];
        List<String> lines = new ArrayList<>();

        for (Example ex : eval) {
            String base = chat(BASE_MODEL, turn(messages(ex.system()), "user", ex.memo()));
            ArrayNode shots = messages(RULES);
            for (Example s : similar(train, ex.memo(), 3)) {          // 비슷한 예시를 대화로 붙임
                turn(shots, "user", s.memo());
                turn(shots, "assistant", s.answer());
            }
            String fewshot = chat(BASE_MODEL, turn(shots, "user", ex.memo()));
            String lora = chat(LORA_MODEL, turn(messages(ex.system()), "user", ex.memo()));

            String[] outs = {base, fewshot, lora};
            for (int i = 0; i < 3; i++) {
                String o = outs[i];
                if (REQUIRED.stream().allMatch(o::contains)) fmt[i]++;
                f1[i] += charF1(o, ex.answer());
            }
            ObjectNode row = JSON.createObjectNode();
            row.put("input", ex.memo()).put("base", base).put("fewshot", fewshot).put("lora", lora).put("ref", ex.answer());
            lines.add(row.toString());
        }
        int n = Math.max(1, eval.size());
        System.out.printf("평가 %d건 (기본 %s · 어댑터 %s)%n", eval.size(), BASE_MODEL, LORA_MODEL);
        IntStream.range(0, 3).forEach(i -> System.out.printf("  %-8s 형식 준수율 %3.0f%% · 글자 겹침 %.2f%n",
                names[i], 100.0 * fmt[i] / n, f1[i] / n));
        Files.write(Path.of("compare.jsonl"), lines, StandardCharsets.UTF_8);
        System.out.println("compare.jsonl 저장 — 검토자 2명이 방식 이름을 가린 채 선호를 표시합니다");
    }

    static String env(String k, String def) {
        return System.getenv().getOrDefault(k, def);
    }
